// T59 tap-a-word hints on English prompts: js/en-glosses.js (generated by
// tools/build-en-glosses.mjs) maps a frame's audioId → that prompt's words, each optionally
// carrying the romanized Nepali word it hints at.
//
// The risk this file guards is a WRONG hint, which is worse than no hint: the learner is
// being graded on producing that Nepali, so a stale or mis-keyed entry teaches the wrong
// answer. Hence the invariants below — the English must still be the prompt's English, and
// every hint must be a word of that same prompt's own Nepali. Un-hinted words are fine and
// deliberately not asserted against: the aligner leaves a word plain rather than guess.
import test from 'node:test';
import assert from 'node:assert/strict';
import { liftGlobals } from '../lift.mjs';

const { EN_GLOSSES } = liftGlobals('js/en-glosses.js', ['EN_GLOSSES']);
const { COURSE } = liftGlobals('js/data.js', ['COURSE']);
const { SanoRomanize } = liftGlobals('js/romanize.js', ['SanoRomanize']);

// The frames js/sano.js can show, keyed the way itemFrames() keys them: the canonical
// sentence under the item id, each alternate frame under `<id>-fN`.
const frames = new Map();
for (const unit of COURSE)
	for (const item of unit.items) {
		frames.set(item.id, { en: item.en, dev: item.dev });
		(item.frames || []).forEach((f, i) => frames.set(item.id + '-f' + (i + 1), { en: f.en, dev: f.dev }));
	}

const words = (s) => String(s).split(/\s+/).filter(Boolean);

test('every key is a frame the app can actually show', () => {
	const orphans = Object.keys(EN_GLOSSES).filter((id) => !frames.has(id));
	assert.deepEqual(orphans, [], 'alignment keys matching no item/frame — stale build?');
});

test('the words rebuild the prompt English exactly', () => {
	// setPrompt finds the aligned English inside the prompt text by substring; if the two
	// ever drift the hint silently disappears, so pin them together here.
	const drifted = [];
	for (const [id, segs] of Object.entries(EN_GLOSSES)) {
		const rebuilt = segs.map((s) => s[0]).join(' ');
		const expected = words(frames.get(id).en).join(' ');
		if (rebuilt !== expected) drifted.push(`${id}: "${rebuilt}" ≠ "${expected}"`);
	}
	assert.deepEqual(drifted, [], 'alignment English no longer matches the item — re-run tools/build-en-glosses.mjs');
});

test('every hint is a contiguous run of that same prompt’s Nepali', () => {
	// The whole point of aligning per prompt: a hint may only ever point at the sentence being
	// asked for. A hint may be a PHRASE — one English word can be several Nepali words
	// ("sorry" is the whole of "maaf garnuhos") — but only a run that actually appears in that
	// sentence, in order. A phrase assembled from words at opposite ends would read as a real
	// Nepali expression while being something the learner should never say.
	const foreign = [];
	for (const [id, segs] of Object.entries(EN_GLOSSES)) {
		const own = words(SanoRomanize.romanize(frames.get(id).dev));
		for (const [en, np] of segs) {
			if (!np) continue;
			const run = words(np);
			const at = own.findIndex((_, i) => run.every((w, k) => own[i + k] === w));
			if (at < 0) foreign.push(`${id}: "${en}" → "${np}" (not a contiguous run of its Nepali)`);
		}
	}
	assert.deepEqual(foreign, [], 'hints pointing outside their own prompt');
});

test('no empty spans, and every entry hints at least one word', () => {
	for (const [id, segs] of Object.entries(EN_GLOSSES)) {
		assert.ok(segs.length > 0, `${id} has no words`);
		for (const seg of segs) {
			assert.ok(typeof seg[0] === 'string' && seg[0].trim().length, `${id} has an empty English span`);
			if (seg.length > 1) assert.ok(typeof seg[1] === 'string' && seg[1].trim().length, `${id} has an empty Nepali hint`);
		}
		// A row with nothing tappable is meant to be absent entirely (the app then renders
		// the prompt plain), so its presence here means the generator changed shape.
		assert.ok(
			segs.some((s) => s.length > 1),
			`${id} is in the lexicon but hints nothing`,
		);
	}
});

test('one Nepali word never hints two different, non-adjacent meanings by accident', () => {
	// Adjacent words sharing a hint are a merged phrase ("at home" → gharamaa) and merge
	// into ONE span, so a repeat of the same hint in one prompt can only be a second sense
	// of that word ("Hello / Goodbye" → namaste). What must never happen is a span
	// repeating immediately, which would mean mergeSegs failed to collapse it.
	for (const [id, segs] of Object.entries(EN_GLOSSES))
		for (let i = 1; i < segs.length; i++)
			assert.notEqual(segs[i][1] ?? null, segs[i - 1][1] ?? null, `${id} has neighbouring spans sharing a hint — mergeSegs regression`);
});
